insert into public.stories (id,section,country,label,sensitive,editor_approved,headline,summary,publisher,published_at,date_only,url,link_is_section,also_reported,is_lead,translations,status) values
('car-hilux','Cars','UAE','corroborated',false,false,'Ninth-generation Toyota Hilux goes on sale in the UAE from AED 107,900','The 2027 pickup comes in six 4x4 versions up to AED 164,900, with a 2.7-litre petrol or 2.8-litre turbo-diesel. The V6 option has been dropped.','YallaMotor','2026-10-21T12:00:00+04:00',true,'https://www.yallamotor.com/news/toyota-hilux-2027-price-in-uae-55787',false,'Toyota UAE website',false,'{"ar":["تويوتا هايلكس الجيل التاسع تطرح في الإمارات بسعر يبدأ من 107,900 درهم","تتوفر شاحنة 2027 بست فئات دفع رباعي حتى 164,900 درهم، بمحرك بنزين 2.7 لتر أو ديزل توربيني 2.8 لتر، مع إلغاء خيار V6."],"fr":["Le Toyota Hilux de neuvième génération en vente aux EAU dès 107 900 AED","Le pick-up 2027 existe en six versions 4x4 jusqu''à 164 900 AED, avec un essence 2,7 l ou un turbo-diesel 2,8 l. Le V6 disparaît."],"de":["Toyota Hilux der neunten Generation in den VAE ab 107.900 AED erhältlich","Den Pick-up 2027 gibt es in sechs Allrad-Versionen bis 164.900 AED, mit 2,7-Liter-Benziner oder 2,8-Liter-Turbodiesel. Der V6 entfällt."]}'::jsonb,'published'),
('car-lexus','Cars','UAE','single',false,false,'Lexus RZ500e electric SUV launches in the UAE at AED 255,000','Lexus''s first locally sold all-electric SUV has 375hp, all-wheel drive and up to 460 km of WLTP range. It is sold through Al-Futtaim Lexus alongside the ES500e saloon.','YallaMotor','2026-10-19T12:00:00+04:00',true,'https://www.yallamotor.com/news/lexus-rz500e-launched-uae-price-specs-55775',false,null,false,'{"ar":["لكزس RZ500e الكهربائية تنطلق في الإمارات بسعر 255,000 درهم","أول SUV كهربائية بالكامل من لكزس تُباع محلياً، بقوة 375 حصاناً ودفع رباعي ومدى يصل إلى 460 كم وفق WLTP، عبر الفطيم لكزس إلى جانب سيدان ES500e."],"fr":["Le SUV électrique Lexus RZ500e lancé aux EAU à 255 000 AED","Premier SUV 100 % électrique de Lexus vendu localement : 375 ch, transmission intégrale et jusqu''à 460 km d''autonomie WLTP, chez Al-Futtaim Lexus aux côtés de la berline ES500e."],"de":["Elektro-SUV Lexus RZ500e startet in den VAE für 255.000 AED","Lexus'' erstes lokal verkauftes Elektro-SUV bietet 375 PS, Allradantrieb und bis zu 460 km WLTP-Reichweite, erhältlich bei Al-Futtaim Lexus neben der ES500e-Limousine."]}'::jsonb,'published'),
('car-freelander','Cars','UAE','single',false,false,'Freelander 8 plug-in hybrid SUV makes its debut in Abu Dhabi','The first model from the new JLR–Chery Freelander brand has 617hp and up to 110 km of electric range. Prices and delivery dates are still to be announced.','YallaMotor','2026-10-21T12:00:00+04:00',true,'https://www.yallamotor.com/news/freelander-8-launched-uae-specs-price-55791',false,null,false,'{"ar":["فريلاندر 8 الهجينة القابلة للشحن تظهر لأول مرة في أبوظبي","أول طراز من علامة فريلاندر الجديدة المشتركة بين JLR وشيري، بقوة 617 حصاناً ومدى كهربائي حتى 110 كم. لم تُعلن الأسعار ومواعيد التسليم بعد."],"fr":["Le SUV hybride rechargeable Freelander 8 fait ses débuts à Abou Dabi","Premier modèle de la nouvelle marque Freelander de JLR et Chery : 617 ch et jusqu''à 110 km en électrique. Prix et livraisons restent à annoncer."],"de":["Plug-in-Hybrid-SUV Freelander 8 feiert Debüt in Abu Dhabi","Das erste Modell der neuen JLR-Chery-Marke Freelander hat 617 PS und bis zu 110 km elektrische Reichweite. Preise und Liefertermine folgen."]}'::jsonb,'published'),
('car-ferrari','Cars','UAE','developing',false,false,'Ferrari Luce, the brand''s first electric car, nears first deliveries','The four-motor Luce has about 1,035hp and a provisional 530 km range, priced near €550,000 in Europe. UAE prices and delivery dates have not been officially confirmed.','YallaMotor','2026-10-27T12:00:00+04:00',true,'https://www.yallamotor.com/news/ferrari-luce-deliveries-price-specs-first-electric-ferrari-uae-55815',false,null,false,'{"ar":["فيراري لوتشي، أول سيارة كهربائية للعلامة، تقترب من التسليمات الأولى","تتمتع لوتشي بأربعة محركات وقوة نحو 1,035 حصاناً ومدى مبدئي 530 كم، بسعر يقارب 550 ألف يورو في أوروبا. لم تُؤكد أسعار الإمارات ومواعيد التسليم رسمياً."],"fr":["La Ferrari Luce, première électrique de la marque, approche des premières livraisons","La Luce à quatre moteurs développe environ 1 035 ch pour une autonomie provisoire de 530 km, à près de 550 000 € en Europe. Prix et livraisons aux EAU non confirmés officiellement."],"de":["Ferrari Luce, das erste Elektroauto der Marke, steht vor den ersten Auslieferungen","Der Luce mit vier Motoren leistet rund 1.035 PS bei vorläufig 530 km Reichweite und kostet in Europa etwa 550.000 €. VAE-Preise und Liefertermine sind nicht offiziell bestätigt."]}'::jsonb,'published'),
('car-peugeot','Cars','UAE','single',false,false,'New Peugeot 408 arrives in the UAE and GCC','The updated fastback crossover comes with a 215hp turbo engine in Allure and GT trims.','YallaMotor','2026-10-21T12:00:00+04:00',true,'https://www.yallamotor.com/news/new-peugeot-408-uae-gcc-launch-specs-55789',false,null,false,'{"ar":["بيجو 408 الجديدة تصل إلى الإمارات والخليج","تأتي الكروس أوفر المحدّثة بمحرك توربيني بقوة 215 حصاناً في فئتي Allure وGT."],"fr":["La nouvelle Peugeot 408 arrive aux EAU et dans le Golfe","Le crossover fastback restylé reçoit un moteur turbo de 215 ch en finitions Allure et GT."],"de":["Neuer Peugeot 408 kommt in die VAE und den Golf","Der überarbeitete Fastback-Crossover erhält einen 215-PS-Turbomotor in den Ausstattungen Allure und GT."]}'::jsonb,'published'),
('car-navara','Cars','UAE','developing',false,false,'New Nissan Navara nears UAE launch as Dubai billboards go up','Engines for the Navara Pro have been confirmed ahead of the pickup''s local launch. Prices are not yet published.','YallaMotor','2026-10-25T12:00:00+04:00',true,'https://www.yallamotor.com/news/nissan-navara-2026-pro-uae-launch-update-55809',false,null,false,'{"ar":["نيسان نافارا الجديدة تقترب من الإطلاق في الإمارات مع لوحات إعلانية في دبي","تأكدت محركات نافارا برو قبل الإطلاق المحلي للشاحنة، ولم تُنشر الأسعار بعد."],"fr":["Le nouveau Nissan Navara approche de son lancement aux EAU","Les moteurs du Navara Pro sont confirmés avant le lancement local, et des panneaux sont apparus à Dubaï. Prix pas encore publiés."],"de":["Neuer Nissan Navara kurz vor VAE-Start, Plakate in Dubai","Die Motoren des Navara Pro sind vor dem lokalen Marktstart bestätigt. Preise wurden noch nicht veröffentlicht."]}'::jsonb,'published'),
('car-icaur','Cars','UAE','single',false,false,'iCAUR V25 makes its global debut, with a UAE launch planned for late 2026','The new SUV is due in the UAE in the fourth quarter of 2026. Specifications and prices for the local market are still to come.','DriveArabia','2026-10-22T12:00:00+04:00',true,'https://www.drivearabia.com/news/2026/10/22/icaur-v25-makes-global-debut-uae-launch-set-for-q4-2026/',false,null,false,'{"ar":["iCAUR V25 تظهر عالمياً لأول مرة وإطلاقها في الإمارات أواخر 2026","من المقرر وصول الـSUV الجديدة إلى الإمارات في الربع الرابع من 2026، ولم تُعلن مواصفات وأسعار السوق المحلية بعد."],"fr":["Le SUV iCAUR V25 fait ses débuts mondiaux, lancement aux EAU fin 2026","Le nouveau SUV est attendu aux EAU au quatrième trimestre 2026. Caractéristiques et prix locaux à venir."],"de":["iCAUR V25 feiert Weltpremiere, VAE-Start Ende 2026 geplant","Das neue SUV soll im vierten Quartal 2026 in die VAE kommen. Technische Daten und lokale Preise folgen."]}'::jsonb,'published'),
('car-roadster','Cars','International','developing',false,false,'Tesla reveals the next-generation Roadster','Tesla showed a company-reported 0.81-second 0–60 mph run. Reported prices start around $200,000 with production targeted for 2028, but none of this is confirmed and there is no official UAE launch.','YallaMotor','2026-10-20T12:00:00+04:00',true,'https://www.yallamotor.com/news/tesla-roadster-revealed-thrusters-sub-1s-0-100-km-h-cost-uae-55781',false,'CNBC',false,'{"ar":["تسلا تكشف الجيل الجديد من رودستر","عرضت تسلا تسارعاً من 0 إلى 60 ميلاً في 0.81 ثانية وفق الشركة. وتشير تقارير إلى سعر يبدأ من نحو 200 ألف دولار وإنتاج مستهدف في 2028، لكن لا شيء من ذلك مؤكد ولا يوجد إطلاق رسمي في الإمارات."],"fr":["Tesla dévoile la nouvelle génération de Roadster","Tesla a montré un 0 à 60 mph en 0,81 seconde, selon la marque. Les prix rapportés débuteraient vers 200 000 $ pour une production visée en 2028, mais rien n''est confirmé et aucun lancement officiel aux EAU n''est prévu."],"de":["Tesla enthüllt den neuen Roadster","Tesla zeigte laut eigenen Angaben einen Sprint von 0 auf 60 mph in 0,81 Sekunden. Berichtete Preise beginnen bei rund 200.000 $, die Produktion ist für 2028 angepeilt – bestätigt ist davon nichts, einen offiziellen VAE-Start gibt es nicht."]}'::jsonb,'published'),
('car-porsche','Cars','International','single',false,false,'Porsche unveils Mission S, a mid-engine supercar concept above the 911','Revealed in New York on 15 October, the concept previews a new family of Porsche supercars. Power, powertrain, price and production timing have not been announced.','YallaMotor','2026-10-20T12:00:00+04:00',true,'https://www.yallamotor.com/news/porsche-mission-s-revealed-mid-engine-supercar-above-911-55785',false,null,false,'{"ar":["بورشه تكشف Mission S، مفهوم سيارة خارقة بمحرك وسطي فوق 911","كُشف المفهوم في نيويورك في 15 أكتوبر ويمهّد لعائلة جديدة من سيارات بورشه الخارقة. لم تُعلن القوة ونوع المحرك والسعر وموعد الإنتاج."],"fr":["Porsche dévoile Mission S, un concept de supercar à moteur central au-dessus de la 911","Présenté à New York le 15 octobre, le concept préfigure une nouvelle famille de supercars. Puissance, motorisation, prix et production n''ont pas été annoncés."],"de":["Porsche zeigt Mission S, ein Mittelmotor-Supersportwagen-Konzept oberhalb des 911","Das am 15. Oktober in New York enthüllte Konzept kündigt eine neue Supersportwagen-Familie an. Leistung, Antrieb, Preis und Produktionsstart sind nicht bekannt."]}'::jsonb,'published'),
('ph-impeach','Politics','Philippines','official',true,false,'Sara Duterte impeachment trial may run into December, Senate President says','Sherwin Gatchalian said the trial resumes on 9 November, with a short pause for 2027 budget debates. The prosecution rested on 15 October, the defence has yet to present its case, and one charge on alleged unexplained wealth remains.','Philippine News Agency','2026-10-27T11:50:00+04:00',false,'https://www.pna.gov.ph/article/vp-sara-impeachment-trial-may-run-through-december-gatchalian',false,null,false,'{"ar":["رئيس مجلس الشيوخ: محاكمة عزل سارة دوتيرتي قد تمتد إلى ديسمبر","قال شيروين غاتشاليان إن المحاكمة تُستأنف في 9 نوفمبر مع توقف قصير لمناقشة ميزانية 2027. أنهى الادعاء مرافعته في 15 أكتوبر ولم يقدّم الدفاع قضيته بعد، وبقيت تهمة واحدة تتعلق بثروة غير مبررة."],"fr":["Le procès en destitution de Sara Duterte pourrait durer jusqu''en décembre","Selon Sherwin Gatchalian, le procès reprend le 9 novembre avec une courte pause pour le budget 2027. L''accusation a clos son dossier le 15 octobre ; la défense doit encore plaider, et un seul chef d''accusation, sur un enrichissement inexpliqué, demeure."],"de":["Amtsenthebungsverfahren gegen Sara Duterte könnte bis Dezember dauern","Senatspräsident Sherwin Gatchalian sagt, der Prozess werde am 9. November fortgesetzt, mit kurzer Pause für die Haushaltsberatungen 2027. Die Anklage hat am 15. Oktober geschlossen, die Verteidigung steht aus; ein Anklagepunkt zu ungeklärtem Vermögen bleibt."]}'::jsonb,'in_review'),
('ph-china','Politics','Philippines','official',true,false,'Manila rules out economic retaliation against China over sea tensions','Palace Press Officer Claire Castro said President Marcos prefers diplomacy and keeps trade separate from defending maritime claims, after China''s ambassador made remarks Manila called threatening.','Philippine News Agency','2026-10-27T11:38:00+04:00',false,'https://www.pna.gov.ph/article/palace-rules-out-economic-retaliation-amid-tensions-with-china',false,null,false,'{"ar":["مانيلا تستبعد الرد الاقتصادي على الصين بسبب التوتر البحري","قالت المتحدثة باسم القصر كلير كاسترو إن الرئيس ماركوس يفضّل الدبلوماسية ويفصل التجارة عن الدفاع عن الحقوق البحرية، بعد تصريحات للسفير الصيني اعتبرتها مانيلا تهديداً."],"fr":["Manille exclut des représailles économiques contre la Chine","La porte-parole Claire Castro indique que le président Marcos privilégie la diplomatie et sépare commerce et défense des droits maritimes, après des propos de l''ambassadeur chinois jugés menaçants."],"de":["Manila schließt wirtschaftliche Vergeltung gegen China aus","Palastsprecherin Claire Castro sagt, Präsident Marcos setze auf Diplomatie und trenne Handel von der Verteidigung maritimer Rechte – nach Äußerungen des chinesischen Botschafters, die Manila als Drohung wertet."]}'::jsonb,'in_review'),
('ph-bato','Politics','Philippines','corroborated',true,false,'Philippine police keep hunting Senator dela Rosa over ICC warrant','Authorities set a one-week surrender deadline and a 50-million-peso bounty for Ronald dela Rosa, wanted by the International Criminal Court over the drug war. The Palace says the search continues if he does not surrender.','Philippine News Agency','2026-10-27T11:22:00+04:00',false,'https://www.pna.gov.ph/article/palace-bato-faces-continued-hunt-if-he-refuses-to-surrender',false,'The Manila Times',false,'{"ar":["الشرطة الفلبينية تواصل ملاحقة السيناتور ديلا روسا بموجب مذكرة الجنائية الدولية","حددت السلطات مهلة أسبوع لتسليم نفسه ومكافأة بقيمة 50 مليون بيزو للقبض على رونالد ديلا روسا المطلوب للمحكمة الجنائية الدولية بسبب حرب المخدرات. ويقول القصر إن البحث سيستمر إن لم يسلّم نفسه."],"fr":["La police philippine poursuit la traque du sénateur dela Rosa, visé par la CPI","Les autorités ont fixé un ultimatum d''une semaine et une prime de 50 millions de pesos contre Ronald dela Rosa, recherché par la Cour pénale internationale pour la guerre antidrogue. La traque continuera s''il ne se rend pas."],"de":["Philippinische Polizei jagt Senator dela Rosa wegen IStGH-Haftbefehl weiter","Behörden setzten Ronald dela Rosa, der vom Internationalen Strafgerichtshof wegen des Drogenkriegs gesucht wird, eine Woche Frist und 50 Millionen Peso Kopfgeld. Stellt er sich nicht, geht die Suche weiter."]}'::jsonb,'in_review'),
('ph-reshuffle','Politics','Philippines','official',true,false,'Marcos swaps transport and public works secretaries','Vince Dizon returns to the Department of Transportation and Giovanni Lopez takes over Public Works and Highways. The Palace said the move is meant to speed up reforms at both agencies.','The Manila Times','2026-10-27T12:00:00+04:00',true,'https://www.manilatimes.net/2026/10/27/podcasts/headlines-dizon-lopez-trade-places-in-reshuffle-october-27-2026/2454223',false,null,false,'{"ar":["ماركوس يتبادل حقيبتي النقل والأشغال العامة بين وزيرين","يعود فينس ديزون إلى وزارة النقل ويتولى جيوفاني لوبيز وزارة الأشغال العامة والطرق، وقال القصر إن الهدف تسريع الإصلاحات في الوزارتين."],"fr":["Marcos intervertit les ministres des Transports et des Travaux publics","Vince Dizon retrouve les Transports et Giovanni Lopez prend les Travaux publics et Routes, un remaniement destiné à accélérer les réformes selon le palais."],"de":["Marcos tauscht Verkehrs- und Bauminister","Vince Dizon kehrt ins Verkehrsministerium zurück, Giovanni Lopez übernimmt Öffentliche Arbeiten und Straßen. Laut Palast sollen so Reformen in beiden Behörden beschleunigt werden."]}'::jsonb,'in_review'),
('ph-pba','Sports & Events','Philippines','single',false,false,'San Miguel and Ginebra open PBA Governors'' Cup quarterfinal','The two rivals began their quarterfinal series on Tuesday evening in Manila.','The Manila Times','2026-10-27T12:00:00+04:00',true,'https://www.manilatimes.net/2026/10/27/podcasts/headlines-dizon-lopez-trade-places-in-reshuffle-october-27-2026/2454223',false,null,false,'{"ar":["سان ميغيل وجينيبرا يفتتحان ربع نهائي كأس الحكام في دوري PBA","بدأ الغريمان سلسلة ربع النهائي مساء الثلاثاء في مانيلا."],"fr":["San Miguel et Ginebra ouvrent leur quart de finale de la Governors'' Cup","Les deux rivaux ont lancé leur série mardi soir à Manille."],"de":["San Miguel und Ginebra eröffnen PBA-Viertelfinale im Governors'' Cup","Die Rivalen starteten am Dienstagabend in Manila in ihre Viertelfinalserie."]}'::jsonb,'published'),
('ma-gov','Politics','Morocco','official',true,false,'Morocco''s new Head of Government presents her programme to Parliament','Fatima Ezzahra El Mansouri set out the government''s five-year plan after the 23 September elections, prioritising purchasing power, jobs for young people, schools, hospitals and water and food security.','Maroc.ma (via MAP)','2026-10-20T12:00:00+04:00',true,'https://maroc.ma/en/news/government-program-political-institutional-contract-rooted-high-royal-trust-will-citizens-during',false,null,false,'{"ar":["رئيسة الحكومة المغربية الجديدة تعرض برنامجها أمام البرلمان","عرضت فاطمة الزهراء المنصوري خطة الحكومة الخماسية بعد انتخابات 23 سبتمبر، مع أولوية للقدرة الشرائية وتشغيل الشباب والمدارس والمستشفيات والأمن المائي والغذائي."],"fr":["La nouvelle cheffe du gouvernement marocain présente son programme au Parlement","Fatima Ezzahra El Mansouri a exposé le plan quinquennal après les élections du 23 septembre : pouvoir d''achat, emploi des jeunes, écoles, hôpitaux, sécurité hydrique et alimentaire."],"de":["Marokkos neue Regierungschefin stellt ihr Programm im Parlament vor","Fatima Ezzahra El Mansouri präsentierte nach den Wahlen vom 23. September den Fünfjahresplan: Kaufkraft, Jobs für junge Menschen, Schulen, Krankenhäuser sowie Wasser- und Ernährungssicherheit."]}'::jsonb,'in_review'),
('ma-afdb','Politics','Morocco','official',false,false,'African Development Bank approves $487 million for Morocco''s reforms','The third phase of the programme supports economic governance, small businesses and climate resilience, and helps Morocco absorb higher energy and transport costs linked to the Middle East crisis.','Maroc.ma (via MAP)','2026-10-22T12:00:00+04:00',true,'https://maroc.ma/en/news/afdb-approves-487-mln-loan-boost-moroccos-structural-reforms-economic-resilience',false,null,false,'{"ar":["البنك الإفريقي للتنمية يوافق على 487 مليون دولار لدعم إصلاحات المغرب","تدعم المرحلة الثالثة من البرنامج الحوكمة الاقتصادية والمقاولات الصغيرة والصمود المناخي، وتساعد المغرب على مواجهة ارتفاع تكاليف الطاقة والنقل المرتبط بأزمة الشرق الأوسط."],"fr":["La Banque africaine de développement accorde 487 millions de dollars au Maroc","La troisième phase du programme soutient la gouvernance économique, les PME et la résilience climatique, et aide le Maroc face à la hausse des coûts de l''énergie et du transport liée à la crise au Moyen-Orient."],"de":["Afrikanische Entwicklungsbank bewilligt Marokko 487 Millionen Dollar","Die dritte Programmphase stärkt Wirtschaftsführung, kleine Unternehmen und Klimaresilienz und hilft Marokko, höhere Energie- und Transportkosten infolge der Nahostkrise abzufedern."]}'::jsonb,'published'),
('ma-futsal','Sports & Events','Morocco','official',false,false,'Morocco beat Angola 5-2 to win a fourth futsal Africa Cup of Nations','The Atlas Lions won the final at the Prince Moulay Abdellah Sports Complex in Rabat.','Maroc.ma (via MAP)','2026-10-22T12:00:00+04:00',true,'https://maroc.ma/en/news/morocco-snatches-4th-futsal-afcon-title',false,null,false,'{"ar":["المغرب يهزم أنغولا 5-2 ويحرز كأس إفريقيا لكرة القدم داخل القاعة للمرة الرابعة","فاز أسود الأطلس بالنهائي في القاعة المغطاة بمجمع الأمير مولاي عبد الله الرياضي في الرباط."],"fr":["Le Maroc bat l''Angola 5-2 et remporte une quatrième CAN de futsal","Les Lions de l''Atlas se sont imposés en finale au complexe sportif Prince Moulay Abdellah de Rabat."],"de":["Marokko schlägt Angola 5:2 und gewinnt zum vierten Mal den Futsal-Afrika-Cup","Die Atlas-Löwen gewannen das Finale im Sportkomplex Prinz Moulay Abdellah in Rabat."]}'::jsonb,'published'),
('ma-hearing','Health & Wellness','Morocco','official',true,false,'Morocco''s Princess Lalla Asmaa launches hearing-health programme phase in Rwanda','With Rwanda''s First Lady, the princess launched the fifth phase of a programme supporting children with hearing loss in Kigali, and the two signed a partnership between their foundations.','Maroc.ma (via MAP)','2026-10-27T12:00:00+04:00',true,'https://maroc.ma/en/news/hrh-princess-lalla-asmaa-rwandas-first-lady-launch-5th-phase-united-we-hear-each-other-better-program',false,null,false,'{"ar":["الأميرة للا أسماء تطلق مرحلة جديدة من برنامج لصحة السمع في رواندا","أطلقت الأميرة مع السيدة الأولى في رواندا المرحلة الخامسة من برنامج يدعم الأطفال ذوي الإعاقة السمعية في كيغالي، ووقّعتا شراكة بين مؤسستيهما."],"fr":["La princesse Lalla Asmaa lance une nouvelle phase d''un programme de santé auditive au Rwanda","Avec la Première dame du Rwanda, elle a lancé à Kigali la cinquième phase d''un programme pour les enfants malentendants et signé un partenariat entre leurs fondations."],"de":["Marokkos Prinzessin Lalla Asmaa startet Hörgesundheitsprogramm in Ruanda","Mit Ruandas First Lady startete sie in Kigali die fünfte Phase eines Programms für hörgeschädigte Kinder und unterzeichnete eine Partnerschaft beider Stiftungen."]}'::jsonb,'in_review'),
('flydubai','GCC','UAE','official',false,false,'UAE President honours flydubai crew from September in-flight incident','Sheikh Mohamed bin Zayed received the crew members involved in the 30 September in-flight incident and awarded them the First Class Order of Zayed II for keeping passengers safe. Sheikh Mohammed bin Rashid attended the reception.','Emirates 24|7 (via WAM)','2026-10-27T22:09:00+04:00',false,'https://www.emirates247.com/uae/uae-president-confers-first-class-order-of-zayed-ii-on-flydubai-crew/7181',false,'Sharjah24 / WAM',true,'{"ar":["رئيس الدولة يكرّم طاقم فلاي دبي في حادثة الطائرة في سبتمبر","استقبل الشيخ محمد بن زايد أفراد طاقم فلاي دبي الذين تعاملوا مع حادثة الرحلة في 30 سبتمبر، ومنحهم وسام زايد الثاني من الطبقة الأولى تقديراً لحفاظهم على سلامة الركاب، بحضور الشيخ محمد بن راشد."],"fr":["Le président des EAU décore l''équipage de flydubai après l''incident de septembre","Cheikh Mohamed ben Zayed a reçu les membres d''équipage impliqués dans l''incident en vol du 30 septembre et leur a remis l''Ordre de Zayed II de première classe pour avoir protégé les passagers, en présence de Cheikh Mohammed ben Rachid."],"de":["VAE-Präsident ehrt flydubai-Crew nach Vorfall im September","Scheich Mohamed bin Zayed empfing die Besatzung, die am 30. September einen Zwischenfall an Bord bewältigt hatte, und verlieh ihr den Zayed-II.-Orden erster Klasse für den Schutz der Passagiere. Scheich Mohammed bin Rashid war anwesend."]}'::jsonb,'published'),
('tehran','GCC','Saudi Arabia','corroborated',true,false,'Saudi, Pakistani and Turkish security chiefs hold de-escalation talks in Tehran','Saudi Defence Minister Prince Khalid bin Salman joined Pakistan''s army chief and Turkey''s intelligence chief in meetings with President Pezeshkian. It is the first high-level Saudi–Iran contact since Houthi attacks on the kingdom escalated, and the sides agreed to keep talking.','CNN','2026-10-26T17:49:00+04:00',false,'https://www.cnn.com/2026/10/26/middleeast/iran-meeting-regional-powers-intl',false,'The National, Khaleej Times',false,'{"ar":["مسؤولون أمنيون سعوديون وباكستانيون وأتراك يجرون محادثات تهدئة في طهران","التقى وزير الدفاع السعودي الأمير خالد بن سلمان وقائد الجيش الباكستاني ورئيس الاستخبارات التركية بالرئيس بزشكيان. وهو أول اتصال سعودي إيراني رفيع منذ تصاعد هجمات الحوثيين على المملكة، واتفق الجانبان على مواصلة الحوار."],"fr":["Les chefs de la sécurité saoudien, pakistanais et turc en pourparlers de désescalade à Téhéran","Le ministre saoudien de la Défense, le prince Khaled ben Salmane, le chef de l''armée pakistanaise et le chef du renseignement turc ont rencontré le président Pezeshkian. C''est le premier contact saoudo-iranien de haut niveau depuis l''escalade des attaques houthies contre le royaume ; les parties ont convenu de poursuivre le dialogue."],"de":["Sicherheitschefs aus Saudi-Arabien, Pakistan und der Türkei verhandeln in Teheran über Deeskalation","Der saudische Verteidigungsminister Prinz Khalid bin Salman traf mit Pakistans Armeechef und dem türkischen Geheimdienstchef Präsident Peseschkian. Es ist der erste hochrangige saudisch-iranische Kontakt seit der Eskalation der Huthi-Angriffe; beide Seiten wollen weiter reden."]}'::jsonb,'in_review'),
('egypt','GCC','Saudi Arabia','corroborated',true,false,'Egypt''s parliament approves defensive military support for Saudi Arabia','Lawmakers authorised President Sisi to provide defensive aid to the kingdom amid continuing Houthi missile and drone attacks. The statement did not say what form the support would take.','The National','2026-10-26T07:57:00+04:00',false,'https://www.thenationalnews.com/news/mena/2026/10/26/live-saudi-arabia-egypt-defence-support/',false,'Institute for the Study of War, Al Arabiya',false,'{"ar":["البرلمان المصري يوافق على دعم عسكري دفاعي للسعودية","فوّض النواب الرئيس السيسي بتقديم دعم دفاعي للمملكة في ظل استمرار هجمات الحوثيين بالصواريخ والمسيّرات، دون تحديد شكل هذا الدعم."],"fr":["Le Parlement égyptien approuve un soutien militaire défensif à l''Arabie saoudite","Les députés ont autorisé le président Sissi à fournir une aide défensive au royaume face aux attaques houthies de missiles et de drones. La forme de ce soutien n''a pas été précisée."],"de":["Ägyptens Parlament billigt defensive Militärhilfe für Saudi-Arabien","Die Abgeordneten ermächtigten Präsident Sisi, das Königreich angesichts anhaltender Raketen- und Drohnenangriffe der Huthi zu unterstützen. Die Form der Hilfe blieb offen."]}'::jsonb,'in_review'),
('flights','GCC','UAE','developing',false,false,'Dubai–Jeddah flights set to resume 30 October; Riyadh route from 8 November','Emirates services between Dubai and Jeddah are scheduled to restart on 30 October, with Dubai–Riyadh expected on 8 November. Riyadh''s main airport reopened after the attacks. Travellers should confirm flight numbers directly with their airline.','Gulf News','2026-10-27T08:06:00+04:00',false,'https://gulfnews.com/uae/us-israel-iran-war-what-uae-residents-need-to-know-today-oct-27-2026-1.500724760',false,'FDD Overnight Brief',false,'{"ar":["استئناف رحلات دبي–جدة في 30 أكتوبر ودبي–الرياض اعتباراً من 8 نوفمبر","تستأنف طيران الإمارات رحلاتها بين دبي وجدة في 30 أكتوبر، ويُتوقع استئناف رحلات دبي–الرياض في 8 نوفمبر بعد إعادة فتح مطار الرياض. على المسافرين التأكد من أرقام الرحلات لدى شركة الطيران."],"fr":["Reprise des vols Dubaï–Djeddah le 30 octobre, Dubaï–Riyad à partir du 8 novembre","Emirates doit reprendre ses vols entre Dubaï et Djeddah le 30 octobre, et la liaison Dubaï–Riyad est attendue le 8 novembre, après la réouverture de l''aéroport de Riyad. Vérifiez vos numéros de vol auprès de la compagnie."],"de":["Flüge Dubai–Dschidda ab 30. Oktober, Dubai–Riad ab 8. November","Emirates will die Verbindung Dubai–Dschidda am 30. Oktober wieder aufnehmen, Dubai–Riad voraussichtlich am 8. November, nachdem der Flughafen Riad wieder geöffnet hat. Flugnummern bitte direkt bei der Airline prüfen."]}'::jsonb,'published'),
('khaled','GCC','UAE','official',false,false,'Abu Dhabi Crown Prince begins official visit to Canada','Sheikh Khaled bin Mohamed arrived in Ottawa for talks with Prime Minister Mark Carney on the UAE–Canada partnership, building on the trade agreement the two countries finalised in July.','The National (via WAM)','2026-10-27T07:39:00+04:00',false,'https://www.thenationalnews.com/news/uae/2026/10/27/sheikh-khaled-arrives-in-canadian-capital-of-ottawa-to-begin-visit-official/',false,null,false,'{"ar":["ولي عهد أبوظبي يبدأ زيارة رسمية إلى كندا","وصل الشيخ خالد بن محمد إلى أوتاوا لإجراء محادثات مع رئيس الوزراء مارك كارني حول الشراكة الإماراتية الكندية، استكمالاً لاتفاقية التجارة التي أُبرمت في يوليو."],"fr":["Le prince héritier d''Abou Dabi entame une visite officielle au Canada","Cheikh Khaled ben Mohamed est arrivé à Ottawa pour s''entretenir avec le Premier ministre Mark Carney du partenariat entre les EAU et le Canada, dans le prolongement de l''accord commercial conclu en juillet."],"de":["Abu Dhabis Kronprinz beginnt Staatsbesuch in Kanada","Scheich Khaled bin Mohamed traf in Ottawa ein, um mit Premierminister Mark Carney über die Partnerschaft beider Länder zu sprechen – aufbauend auf dem im Juli abgeschlossenen Handelsabkommen."]}'::jsonb,'published'),
('flagday','GCC','UAE','official',false,false,'Sheikh Mohammed calls on everyone in the UAE to raise the flag on 3 November','The Vice President asked citizens and residents to take part in Flag Day next Tuesday.','Emirates 24|7','2026-10-27T12:00:00+04:00',true,'https://www.emirates247.com/uae',true,null,false,'{"ar":["الشيخ محمد بن راشد يدعو الجميع لرفع العلم في 3 نوفمبر","دعا نائب رئيس الدولة المواطنين والمقيمين إلى المشاركة في يوم العلم يوم الثلاثاء المقبل."],"fr":["Cheikh Mohammed appelle chacun à hisser le drapeau le 3 novembre","Le vice-président a invité citoyens et résidents à participer à la Journée du drapeau mardi prochain."],"de":["Scheich Mohammed ruft zum Flaggehissen am 3. November auf","Der Vizepräsident bat Bürger und Einwohner, sich am kommenden Dienstag am Flaggentag zu beteiligen."]}'::jsonb,'published'),
('qatar-uae','GCC','Qatar','official',false,false,'Qatar and UAE foreign ministers discuss bilateral ties by phone','Qatar''s Prime Minister and Foreign Minister and the UAE Foreign Minister reviewed cooperation and regional developments, according to Qatar''s Foreign Ministry.','Middle East Eye (citing Qatar MoFA)','2026-10-18T21:47:00+04:00',false,'https://www.middleeasteye.net/live-blog/live-blog-update/qatar-uae-discuss-strengthening-ties-and-regional-developments',false,null,false,'{"ar":["وزيرا خارجية قطر والإمارات يبحثان العلاقات الثنائية هاتفياً","استعرض رئيس الوزراء وزير الخارجية القطري ووزير الخارجية الإماراتي سبل التعاون والمستجدات الإقليمية، وفق وزارة الخارجية القطرية."],"fr":["Les ministres des Affaires étrangères du Qatar et des EAU évoquent leurs relations","Le Premier ministre et ministre des Affaires étrangères qatari et son homologue émirien ont passé en revue leur coopération et la situation régionale, selon le ministère qatari."],"de":["Außenminister Katars und der VAE beraten telefonisch über Beziehungen","Katars Premier- und Außenminister und der VAE-Außenminister sprachen laut katarischem Außenministerium über Zusammenarbeit und die Lage in der Region."]}'::jsonb,'published'),
('lng','GCC','Qatar','official',true,false,'Qatar''s Emir says damage to energy facilities disrupted LNG exports','The Emir said Iranian attacks on the Gulf damaged facilities and interrupted Qatar''s liquefied natural gas shipments.','Khaleej Times','2026-10-13T12:00:00+04:00',true,'https://www.khaleejtimes.com/world/mena/us-israel-iran-lebanon-war-live-updates-october-13-2026',false,null,false,'{"ar":["أمير قطر: أضرار منشآت الطاقة عطّلت صادرات الغاز المسال","قال الأمير إن الهجمات الإيرانية على الخليج ألحقت أضراراً بمنشآت أدت إلى توقف شحنات الغاز الطبيعي المسال القطرية."],"fr":["L''émir du Qatar affirme que des dégâts sur des sites énergétiques ont perturbé les exportations de GNL","Selon l''émir, les attaques iraniennes contre le Golfe ont endommagé des installations et interrompu les livraisons de gaz naturel liquéfié du Qatar."],"de":["Katars Emir: Schäden an Energieanlagen stören LNG-Exporte","Laut dem Emir haben iranische Angriffe auf die Golfregion Anlagen beschädigt und Katars Flüssiggaslieferungen unterbrochen."]}'::jsonb,'in_review'),
('macron','GCC','Bahrain','single',false,false,'Bahrain''s King Hamad welcomes Macron as France seeks more Gulf diesel','The French president visited Sakhir Palace while lining up additional diesel supplies from the Gulf to ease high fuel prices at home.','Al Jazeera','2026-10-20T12:00:00+04:00',true,'https://www.aljazeera.com/where/kuwait/',true,null,false,'{"ar":["ملك البحرين يستقبل ماكرون وفرنسا تسعى لمزيد من الديزل الخليجي","زار الرئيس الفرنسي قصر الصخير في وقت تسعى فيه بلاده لتأمين إمدادات ديزل إضافية من الخليج لتخفيف ارتفاع أسعار الوقود."],"fr":["Le roi de Bahreïn reçoit Macron, la France cherche davantage de diesel du Golfe","Le président français s''est rendu au palais de Sakhir alors que Paris cherche à sécuriser des livraisons de diesel supplémentaires pour contenir la hausse des prix à la pompe."],"de":["Bahrains König empfängt Macron – Frankreich sucht mehr Diesel aus dem Golf","Der französische Präsident besuchte den Sakhir-Palast, während Paris zusätzliche Dieselmengen sichern will, um die hohen Spritpreise zu dämpfen."]}'::jsonb,'published'),
('openai-uae','AI','UAE','single',false,false,'OpenAI reported to be close to a $30 billion round involving UAE investors','A newsletter roundup reports OpenAI is nearing a funding round with UAE backers and Coatue at a $1.25 trillion valuation. Not yet confirmed by the company.','AI Weekly (roundup)','2026-10-27T12:00:00+04:00',true,'https://aiweekly.co/ai-news-today/edition/2026-10-27',false,null,false,'{"ar":["تقارير: OpenAI تقترب من جولة تمويل بـ30 مليار دولار بمشاركة مستثمرين إماراتيين","تفيد نشرة إخبارية بأن OpenAI تقترب من جولة تمويل مع داعمين إماراتيين وشركة Coatue بتقييم 1.25 تريليون دولار. لم تؤكد الشركة ذلك بعد."],"fr":["OpenAI serait proche d''une levée de 30 milliards de dollars avec des investisseurs émiriens","Selon une newsletter, OpenAI finaliserait un tour de table avec des investisseurs des EAU et Coatue, valorisant l''entreprise à 1 250 milliards de dollars. Non confirmé par l''entreprise."],"de":["OpenAI angeblich kurz vor 30-Milliarden-Runde mit Investoren aus den VAE","Laut einem Newsletter steht OpenAI vor einer Finanzierungsrunde mit Geldgebern aus den VAE und Coatue bei 1,25 Billionen Dollar Bewertung. Vom Unternehmen nicht bestätigt."]}'::jsonb,'published'),
('gemini','AI','International','official',false,false,'Google launches a Gemini agent that carries out workplace tasks','Google Cloud introduced a single work agent with its own account, permissions and spending cap, alongside a local meeting-notes app for Mac and Gemini Enterprise queries over company data.','HelloGrowth (citing Google Cloud)','2026-10-08T12:00:00+04:00',true,'https://hellogrowth.ai/en/blog/google-ai-news-october-2026',false,null,false,'{"ar":["غوغل تطلق وكيل Gemini لتنفيذ مهام العمل","قدّمت Google Cloud وكيلاً موحداً للعمل بحساب وصلاحيات وسقف إنفاق خاص به، إلى جانب تطبيق لتدوين ملاحظات الاجتماعات محلياً على ماك واستعلامات Gemini Enterprise على بيانات الشركات."],"fr":["Google lance un agent Gemini qui exécute des tâches professionnelles","Google Cloud a présenté un agent unique doté de son propre compte, de ses autorisations et d''un plafond de dépenses, ainsi qu''une application Mac de prise de notes locale et des requêtes Gemini Enterprise sur les données d''entreprise."],"de":["Google startet Gemini-Agenten für Büroaufgaben","Google Cloud stellte einen Arbeitsagenten mit eigenem Konto, eigenen Rechten und Ausgabenlimit vor, dazu eine Mac-App für lokale Besprechungsnotizen und Gemini-Enterprise-Abfragen über Firmendaten."]}'::jsonb,'published'),
('msft','AI','International','single',false,false,'Microsoft adds on-device AI models and agent security controls to Windows','New Windows features run AI models locally and add security tools for autonomous agents, launched with a Surface Laptop Ultra built on Nvidia chips.','MarketingProfs (weekly roundup)','2026-10-09T12:00:00+04:00',true,'https://www.marketingprofs.com/opinions/2026/56118/ai-update-october-09-2026-ai-news-and-views-from-the-past-week',false,null,false,'{"ar":["مايكروسوفت تضيف نماذج ذكاء اصطناعي محلية وضوابط أمان للوكلاء في ويندوز","تشغّل ميزات ويندوز الجديدة نماذج الذكاء الاصطناعي على الجهاز وتضيف أدوات أمان للوكلاء المستقلين، مع إطلاق Surface Laptop Ultra بشرائح إنفيديا."],"fr":["Microsoft ajoute à Windows des modèles d''IA locaux et des contrôles de sécurité pour les agents","Les nouvelles fonctions de Windows exécutent des modèles d''IA sur l''appareil et ajoutent des outils de sécurité pour les agents autonomes, avec un Surface Laptop Ultra équipé de puces Nvidia."],"de":["Microsoft bringt lokale KI-Modelle und Agenten-Sicherheit in Windows","Neue Windows-Funktionen führen KI-Modelle direkt auf dem Gerät aus und ergänzen Sicherheitswerkzeuge für autonome Agenten; dazu kommt ein Surface Laptop Ultra mit Nvidia-Chips."]}'::jsonb,'published'),
('china-gap','AI','International','single',false,false,'Chinese AI models now trail top US systems by about 3% on benchmarks','Bloomberg Intelligence estimates the gap narrowed from roughly 15% earlier this year.','MarketingProfs (citing Bloomberg Intelligence)','2026-10-09T12:00:00+04:00',true,'https://www.marketingprofs.com/opinions/2026/56118/ai-update-october-09-2026-ai-news-and-views-from-the-past-week',false,null,false,'{"ar":["النماذج الصينية باتت تتأخر عن الأمريكية بنحو 3% فقط","تقدّر Bloomberg Intelligence أن الفجوة تقلصت من نحو 15% في وقت سابق من هذا العام."],"fr":["Les modèles d''IA chinois ne sont plus qu''à environ 3 % des meilleurs systèmes américains","Bloomberg Intelligence estime que l''écart est passé d''environ 15 % en début d''année à 3 %."],"de":["Chinesische KI-Modelle liegen nur noch rund 3 % hinter US-Spitzenmodellen","Bloomberg Intelligence schätzt, dass der Abstand Anfang des Jahres noch etwa 15 % betrug."]}'::jsonb,'published'),
('taskforce','AI','International','developing',true,false,'New US AI task force weighs regulation against innovation','The White House''s new superintelligence task force must balance competing priorities as it drafts recommendations for federal AI policy.','MarketingProfs (weekly roundup)','2026-10-09T12:00:00+04:00',true,'https://www.marketingprofs.com/opinions/2026/56118/ai-update-october-09-2026-ai-news-and-views-from-the-past-week',false,null,false,'{"ar":["فريق أمريكي جديد للذكاء الاصطناعي يوازن بين التنظيم والابتكار","على فريق البيت الأبيض الجديد المعني بالذكاء الفائق التوفيق بين أولويات متنافسة أثناء صياغة توصيات السياسة الفيدرالية للذكاء الاصطناعي."],"fr":["Le nouveau groupe de travail américain sur l''IA tiraillé entre régulation et innovation","Le groupe de la Maison Blanche consacré à la superintelligence doit concilier des priorités concurrentes pour rédiger ses recommandations sur la politique fédérale en matière d''IA."],"de":["Neue US-Arbeitsgruppe zu KI zwischen Regulierung und Innovation","Die neue Superintelligenz-Arbeitsgruppe des Weißen Hauses muss konkurrierende Prioritäten ausgleichen, während sie Empfehlungen für die KI-Politik des Bundes erarbeitet."]}'::jsonb,'in_review'),
('robot','AI','International','official',false,false,'MIT builds a paper-thin swimming robot powered by living muscle','Light-triggered muscle cells let the robot swim and steer, a step toward small self-healing biological machines.','ScienceDaily (MIT release)','2026-10-23T12:00:00+04:00',true,'https://www.sciencedaily.com/news/computers_math/artificial_intelligence/',false,null,false,'{"ar":["معهد MIT يطوّر روبوتاً سابحاً رقيقاً كالورق يعمل بعضلات حية","تتيح خلايا عضلية تستجيب للضوء للروبوت السباحة والتوجيه، في خطوة نحو آلات حيوية صغيرة ذاتية الإصلاح."],"fr":["Le MIT crée un robot nageur fin comme du papier, mû par du muscle vivant","Des cellules musculaires activées par la lumière permettent au robot de nager et de se diriger, un pas vers de petites machines biologiques capables de se réparer."],"de":["MIT baut hauchdünnen Schwimmroboter mit lebendem Muskelgewebe","Lichtgesteuerte Muskelzellen lassen den Roboter schwimmen und steuern – ein Schritt zu kleinen, selbstheilenden biologischen Maschinen."]}'::jsonb,'published'),
('deepseek','AI','International','single',false,false,'DeepSeek reportedly raises $15 billion despite US restrictions','Reports of the funding emerged on 22 October. The company has not confirmed the figure.','TechLatest (weekly roundup)','2026-10-22T12:00:00+04:00',true,'https://techlatestnet.substack.com/p/techlatest-ai-and-tech-weekly-39',false,null,false,'{"ar":["تقارير عن جمع DeepSeek تمويلاً بقيمة 15 مليار دولار رغم القيود الأمريكية","ظهرت أنباء التمويل في 22 أكتوبر، ولم تؤكد الشركة الرقم."],"fr":["DeepSeek aurait levé 15 milliards de dollars malgré les restrictions américaines","L''information est apparue le 22 octobre. L''entreprise n''a pas confirmé le montant."],"de":["DeepSeek soll trotz US-Beschränkungen 15 Milliarden Dollar eingesammelt haben","Berichte über die Finanzierung tauchten am 22. Oktober auf. Das Unternehmen hat die Summe nicht bestätigt."]}'::jsonb,'published'),
('prostate','Health & Wellness','International','official',true,false,'Blood proteins may signal prostate cancer risk 15 years before diagnosis','An Oxford Population Health study found certain blood proteins linked to later prostate cancer. It is an association study and not yet a screening test.','Medical News Today','2026-10-27T12:00:00+04:00',true,'https://www.medicalnewstoday.com/news',true,null,false,'{"ar":["بروتينات في الدم قد تكشف خطر سرطان البروستاتا قبل 15 عاماً من التشخيص","وجدت دراسة من جامعة أكسفورد ارتباطاً بين بروتينات معينة في الدم والإصابة لاحقاً بسرطان البروستاتا. إنها دراسة ارتباط وليست اختبار فحص بعد."],"fr":["Des protéines sanguines pourraient signaler un risque de cancer de la prostate 15 ans avant le diagnostic","Une étude d''Oxford Population Health associe certaines protéines du sang à un cancer de la prostate ultérieur. Il s''agit d''une association, pas encore d''un test de dépistage."],"de":["Blutproteine könnten Prostatakrebs-Risiko 15 Jahre vor der Diagnose anzeigen","Eine Studie von Oxford Population Health fand bestimmte Blutproteine, die mit späterem Prostatakrebs zusammenhängen. Es handelt sich um eine Assoziationsstudie, noch nicht um einen Suchtest."]}'::jsonb,'in_review'),
('who-obesity','Health & Wellness','International','official',true,false,'WHO issues its first global guidelines on child and adolescent obesity','The World Health Organization published its first worldwide guidance on preventing and managing obesity in children and teenagers.','World Health Organization','2026-10-07T12:00:00+04:00',true,'https://www.who.int/news-room/headlines/1?get=974',true,null,false,'{"ar":["منظمة الصحة العالمية تصدر أول إرشادات عالمية لسمنة الأطفال والمراهقين","نشرت المنظمة أول توجيهات عالمية للوقاية من السمنة لدى الأطفال والمراهقين وعلاجها."],"fr":["L''OMS publie ses premières lignes directrices mondiales sur l''obésité de l''enfant et de l''adolescent","L''Organisation mondiale de la santé a publié ses premières recommandations mondiales pour prévenir et prendre en charge l''obésité chez les enfants et les adolescents."],"de":["WHO veröffentlicht erste globale Leitlinien zu Adipositas bei Kindern und Jugendlichen","Die Weltgesundheitsorganisation hat erstmals weltweite Empfehlungen zur Vorbeugung und Behandlung von Übergewicht bei Kindern und Jugendlichen vorgelegt."]}'::jsonb,'in_review'),
('who-mh','Health & Wellness','International','official',true,false,'WHO urges a shift from institutional to community-based mental health care','The agency called on countries to move mental health services closer to where people live.','World Health Organization','2026-10-09T12:00:00+04:00',true,'https://www.who.int/news-room/headlines/1?get=974',true,null,false,'{"ar":["الصحة العالمية تدعو للانتقال إلى رعاية نفسية مجتمعية بدلاً من المؤسسية","دعت المنظمة الدول إلى تقريب خدمات الصحة النفسية من أماكن عيش الناس."],"fr":["L''OMS appelle à passer d''une psychiatrie institutionnelle à des soins de proximité","L''agence demande aux pays de rapprocher les services de santé mentale des lieux de vie des patients."],"de":["WHO fordert Wechsel von stationärer zu gemeindenaher psychiatrischer Versorgung","Die Organisation ruft die Länder auf, psychische Gesundheitsdienste näher an den Wohnort der Menschen zu bringen."]}'::jsonb,'in_review'),
('cavities','Health & Wellness','International','official',true,false,'Painted-on liquid stopped cavities in young children without drilling','A large clinical trial in young children found a liquid brushed onto teeth in seconds halted tooth decay without injections or anaesthesia.','ScienceDaily','2026-10-25T12:00:00+04:00',true,'https://www.sciencedaily.com/',true,null,false,'{"ar":["سائل يُدهن على الأسنان أوقف التسوس لدى الأطفال دون حفر","وجدت تجربة سريرية كبيرة على أطفال صغار أن سائلاً يُدهن على الأسنان في ثوانٍ أوقف التسوس دون حقن أو تخدير."],"fr":["Un liquide appliqué sur les dents a stoppé les caries chez de jeunes enfants, sans fraisage","Un vaste essai clinique montre qu''un liquide badigeonné en quelques secondes arrête la carie, sans piqûre ni anesthésie."],"de":["Aufgepinselte Flüssigkeit stoppt Karies bei Kleinkindern ohne Bohren","Eine große klinische Studie mit kleinen Kindern zeigt: Eine in Sekunden aufgetragene Flüssigkeit stoppte Karies ohne Spritzen oder Betäubung."]}'::jsonb,'in_review'),
('bp-meds','Health & Wellness','International','official',true,false,'Skipping blood pressure pills erodes much of their heart protection','An analysis of more than 91,000 people linked missed doses to a large loss of protection against heart attack and stroke. Do not change medication without talking to your doctor.','ScienceDaily','2026-10-25T12:00:00+04:00',true,'https://www.sciencedaily.com/',true,null,false,'{"ar":["تفويت أدوية ضغط الدم يُفقدها جزءاً كبيراً من حمايتها للقلب","ربط تحليل لأكثر من 91 ألف شخص بين الجرعات الفائتة وفقدان كبير للحماية من النوبات القلبية والسكتات. لا تغيّر دواءك دون استشارة طبيبك."],"fr":["Sauter ses comprimés contre l''hypertension réduit fortement leur protection cardiaque","Une analyse portant sur plus de 91 000 personnes associe les oublis de prise à une nette perte de protection contre l''infarctus et l''AVC. Ne modifiez pas votre traitement sans avis médical."],"de":["Vergessene Blutdrucktabletten kosten viel Herzschutz","Eine Auswertung von über 91.000 Menschen bringt ausgelassene Dosen mit einem deutlichen Verlust des Schutzes vor Herzinfarkt und Schlaganfall in Verbindung. Medikamente nur nach Rücksprache mit dem Arzt ändern."]}'::jsonb,'in_review'),
('petrel','Health & Wellness','International','developing',true,false,'Early data suggest weight-loss drug petrelintide has fewer stomach side effects','Early research on the amylin-based medicine points to fewer gastrointestinal effects than GLP-1 drugs. Larger trials are still needed.','Medical News Today','2026-10-24T12:00:00+04:00',true,'https://www.medicalnewstoday.com/news',true,null,false,'{"ar":["بيانات أولية: دواء بيتريلينتايد لإنقاص الوزن بآثار هضمية أقل","تشير أبحاث أولية على هذا الدواء القائم على الأميلين إلى آثار جانبية هضمية أقل من أدوية GLP-1، ولا تزال هناك حاجة لتجارب أوسع."],"fr":["Premières données : le pétrélintide ferait maigrir avec moins d''effets digestifs","Des recherches préliminaires sur ce médicament à base d''amyline suggèrent moins d''effets gastro-intestinaux que les GLP-1. Des essais plus larges restent nécessaires."],"de":["Erste Daten: Abnehmmittel Petrelintid mit weniger Magen-Darm-Beschwerden","Frühe Forschung zu dem Amylin-basierten Wirkstoff deutet auf weniger Verdauungsnebenwirkungen als bei GLP-1-Mitteln hin. Größere Studien stehen noch aus."]}'::jsonb,'in_review'),
('exercise','Health & Wellness','International','official',true,false,'Regular exercise reshapes the nerves that control the heart','Researchers found training changes cardiac nerves, with different effects on the heart''s left and right sides.','ScienceDaily','2026-10-26T12:00:00+04:00',true,'https://www.sciencedaily.com/news/top/health/',true,null,false,'{"ar":["التمارين المنتظمة تعيد تشكيل الأعصاب التي تتحكم في القلب","وجد باحثون أن التدريب يغيّر أعصاب القلب بتأثيرات مختلفة على جانبيه الأيمن والأيسر."],"fr":["L''exercice régulier remodèle les nerfs qui contrôlent le cœur","Des chercheurs montrent que l''entraînement modifie les nerfs cardiaques, avec des effets différents côté gauche et côté droit."],"de":["Regelmäßiger Sport verändert die Nerven, die das Herz steuern","Forschende fanden, dass Training die Herznerven umbaut – mit unterschiedlichen Effekten auf der linken und rechten Seite."]}'::jsonb,'in_review'),
('brewers','Sports & Events','International','corroborated',false,false,'Brewers rout Rays 10-1 to lead World Series 3-0','Milwaukee scored eight runs in the fifth inning in St Petersburg and is one win from its first title. Game 4 result to follow.','Morning Star','2026-10-27T12:00:00+04:00',true,'https://morningstaronline.co.uk/article/sport-brief-october-27-2026',false,'WiLD 102, NNY360',false,'{"ar":["برورز يسحق رايز 10-1 ويتقدم 3-0 في بطولة العالم للبيسبول","سجّل ميلووكي ثماني نقاط في الشوط الخامس في سانت بطرسبرغ وبات على بُعد فوز واحد من لقبه الأول. نتيجة المباراة الرابعة لاحقاً."],"fr":["Les Brewers écrasent les Rays 10-1 et mènent 3-0 en Série mondiale","Milwaukee a inscrit huit points à la cinquième manche à St. Petersburg et n''est plus qu''à une victoire de son premier titre. Résultat du match 4 à suivre."],"de":["Brewers schlagen Rays 10:1 und führen in der World Series 3:0","Milwaukee erzielte im fünften Inning acht Runs in St. Petersburg und ist einen Sieg vom ersten Titel entfernt. Ergebnis von Spiel 4 folgt."]}'::jsonb,'published'),
('asiancup','Sports & Events','Saudi Arabia','official',false,false,'Saudi Arabia confirms January start for the 2027 Asian Cup','Organisers say the tournament will begin on schedule despite the ongoing attacks on the kingdom.','Al Jazeera','2026-10-26T12:00:00+04:00',true,'https://www.aljazeera.com/where/saudi-arabia/',true,null,false,'{"ar":["السعودية تؤكد انطلاق كأس آسيا 2027 في يناير","يقول المنظمون إن البطولة ستنطلق في موعدها رغم الهجمات المستمرة على المملكة."],"fr":["L''Arabie saoudite confirme le coup d''envoi de la Coupe d''Asie 2027 en janvier","Les organisateurs assurent que le tournoi débutera comme prévu malgré les attaques contre le royaume."],"de":["Saudi-Arabien bestätigt Start des Asien-Cups 2027 im Januar","Die Organisatoren sagen, das Turnier beginne trotz der Angriffe auf das Königreich planmäßig."]}'::jsonb,'published'),
('dakar','Sports & Events','Saudi Arabia','developing',false,false,'Dakar Rally 2027 moved out of Saudi Arabia','The rally''s 2027 edition will be held elsewhere because of the regional conflict. A new host has not been named in this report.','Al Jazeera','2026-10-26T12:00:00+04:00',true,'https://www.aljazeera.com/where/saudi-arabia/',true,null,false,'{"ar":["نقل رالي داكار 2027 خارج السعودية","ستقام نسخة 2027 في مكان آخر بسبب الصراع الإقليمي، ولم يُذكر المضيف الجديد في هذا التقرير."],"fr":["Le Rallye Dakar 2027 quitte l''Arabie saoudite","L''édition 2027 se tiendra ailleurs en raison du conflit régional. Le nouveau pays hôte n''est pas précisé."],"de":["Rallye Dakar 2027 wird aus Saudi-Arabien verlegt","Die Ausgabe 2027 findet wegen des regionalen Konflikts woanders statt. Ein neuer Gastgeber wird in diesem Bericht nicht genannt."]}'::jsonb,'published'),
('gulfcup','Sports & Events','Saudi Arabia','corroborated',false,false,'Saudi Arabia beat UAE 2-0 to win the Arabian Gulf Cup','The win in the final gave Saudi Arabia its first Gulf Cup title in 22 years, after a semi-final penalty shootout against Qatar.','VAVEL','2026-10-06T23:00:00+04:00',false,'https://www.vavel.com/en-us/soccer/2026/10/06/1274110-saudi-arabia-vs-united-arab-emirates-live-score-gulf-cup-final.html',false,'Arab News',false,'{"ar":["السعودية تهزم الإمارات 2-0 وتتوج بكأس الخليج","منح الفوز في النهائي السعودية أول لقب خليجي منذ 22 عاماً، بعد تخطي قطر بركلات الترجيح في نصف النهائي."],"fr":["L''Arabie saoudite bat les EAU 2-0 et remporte la Coupe du Golfe","Cette victoire en finale offre aux Saoudiens leur premier titre depuis 22 ans, après une demi-finale gagnée aux tirs au but contre le Qatar."],"de":["Saudi-Arabien schlägt die VAE 2:0 und gewinnt den Golfpokal","Mit dem Finalsieg holt Saudi-Arabien den ersten Golfpokal seit 22 Jahren, nach einem Halbfinal-Elfmeterschießen gegen Katar."]}'::jsonb,'published'),
('dsc','Sports & Events','UAE','official',false,false,'Dubai Sports Council publishes November and December events calendar','The season calendar lists padel, triathlon, sailing, rugby and cricket. Dubai Fitness Challenge runs 31 October to 29 November with Dubai Ride on 1 November and Dubai Run on 22 November.','Dubai Week','2026-10-27T12:00:00+04:00',true,'https://www.dubaiweek.ae/dubai-sports-events-calendar-november-december-2026/',false,null,false,'{"ar":["مجلس دبي الرياضي ينشر روزنامة فعاليات نوفمبر وديسمبر","تضم الروزنامة البادل والترايثلون والإبحار والرغبي والكريكيت. ويمتد تحدي دبي للياقة من 31 أكتوبر إلى 29 نوفمبر، مع دبي رايد في 1 نوفمبر ودبي رن في 22 نوفمبر."],"fr":["Le Dubai Sports Council publie son calendrier de novembre et décembre","Au programme : padel, triathlon, voile, rugby et cricket. Le Dubai Fitness Challenge se déroule du 31 octobre au 29 novembre, avec la Dubai Ride le 1er novembre et la Dubai Run le 22."],"de":["Dubai Sports Council veröffentlicht Veranstaltungskalender für November und Dezember","Im Kalender stehen Padel, Triathlon, Segeln, Rugby und Cricket. Die Dubai Fitness Challenge läuft vom 31. Oktober bis 29. November, mit Dubai Ride am 1. und Dubai Run am 22. November."]}'::jsonb,'published'),
('lula','Politics','International','corroborated',true,false,'Lula defeats Flávio Bolsonaro in Brazil''s presidential runoff','The 80-year-old president won a close second round. The main opposition party accepted the result, though Bolsonaro has not conceded. UAE leaders sent congratulations.','NPR','2026-10-25T12:00:00+04:00',true,'https://www.npr.org/sections/world/',true,'Democracy Now!, Sharjah24 / WAM',false,'{"ar":["لولا يهزم فلافيو بولسونارو في جولة الإعادة الرئاسية بالبرازيل","فاز الرئيس البالغ 80 عاماً في جولة ثانية متقاربة. وقبل حزب المعارضة الرئيسي النتيجة، لكن بولسونارو لم يعترف بالهزيمة. وهنّأه قادة الإمارات."],"fr":["Lula bat Flávio Bolsonaro au second tour de la présidentielle brésilienne","Le président de 80 ans l''emporte de peu. Le principal parti d''opposition reconnaît le résultat, mais Bolsonaro n''a pas concédé. Les dirigeants des EAU l''ont félicité."],"de":["Lula besiegt Flávio Bolsonaro in Brasiliens Stichwahl","Der 80-jährige Präsident gewann knapp. Die größte Oppositionspartei erkennt das Ergebnis an, Bolsonaro hat seine Niederlage aber nicht eingeräumt. Die VAE-Führung gratulierte."]}'::jsonb,'in_review'),
('ceasefire','Politics','International','developing',true,false,'Russia and Ukraine agree a ceasefire limited to one occupied city','The local truce took effect early Tuesday to allow a US-brokered humanitarian mission. Strikes continue elsewhere.','NPR','2026-10-27T12:00:00+04:00',true,'https://www.npr.org/sections/world/',true,null,false,'{"ar":["روسيا وأوكرانيا تتفقان على وقف إطلاق نار يقتصر على مدينة محتلة واحدة","دخلت الهدنة المحلية حيز التنفيذ صباح الثلاثاء لإتاحة مهمة إنسانية بوساطة أمريكية، فيما تستمر الضربات في مناطق أخرى."],"fr":["Russie et Ukraine conviennent d''un cessez-le-feu limité à une ville occupée","La trêve locale est entrée en vigueur mardi matin pour permettre une mission humanitaire négociée par les États-Unis. Les frappes se poursuivent ailleurs."],"de":["Russland und Ukraine vereinbaren Waffenruhe für eine besetzte Stadt","Die lokale Feuerpause trat am Dienstagmorgen in Kraft, um eine von den USA vermittelte humanitäre Mission zu ermöglichen. Andernorts gehen die Angriffe weiter."]}'::jsonb,'in_review'),
('israel','Politics','International','developing',true,false,'Israelis vote in high numbers in a pivotal election','Turnout is the highest in decades in a vote that could change the country''s leadership. Results are pending.','NPR','2026-10-27T12:00:00+04:00',true,'https://www.npr.org/sections/world/',true,null,false,'{"ar":["إقبال كبير للإسرائيليين على التصويت في انتخابات حاسمة","سُجّلت أعلى نسبة مشاركة منذ عقود في تصويت قد يغيّر قيادة البلاد. النتائج لم تُعلن بعد."],"fr":["Forte participation pour des élections décisives en Israël","La participation est la plus élevée depuis des décennies dans un scrutin qui pourrait changer la direction du pays. Résultats attendus."],"de":["Hohe Beteiligung bei richtungsweisender Wahl in Israel","Die Wahlbeteiligung ist die höchste seit Jahrzehnten; die Wahl könnte die Führung des Landes verändern. Ergebnisse stehen noch aus."]}'::jsonb,'in_review'),
('serbia','Politics','International','single',true,false,'Student-backed movement wins Serbia''s parliamentary election','The result ends more than a decade of dominance by the governing populist party.','NPR','2026-10-26T12:00:00+04:00',true,'https://www.npr.org/sections/world/',true,null,false,'{"ar":["حركة مدعومة من الطلاب تفوز بالانتخابات البرلمانية في صربيا","تنهي النتيجة أكثر من عقد من هيمنة الحزب الشعبوي الحاكم."],"fr":["Un mouvement soutenu par les étudiants remporte les législatives en Serbie","Le résultat met fin à plus d''une décennie de domination du parti populiste au pouvoir."],"de":["Von Studierenden getragene Bewegung gewinnt Parlamentswahl in Serbien","Das Ergebnis beendet mehr als ein Jahrzehnt der Vorherrschaft der regierenden populistischen Partei."]}'::jsonb,'in_review'),
('midterms','Politics','International','single',true,false,'Democrats hold a slight edge a week before US midterms, poll finds','The NPR/PBS News/Marist survey shows a narrow Democratic lead ahead of Election Day.','NPR','2026-10-27T12:00:00+04:00',true,'https://www.npr.org/sections/world/',true,null,false,'{"ar":["استطلاع: الديمقراطيون يتقدمون بفارق طفيف قبل أسبوع من الانتخابات النصفية الأمريكية","يُظهر استطلاع NPR/PBS News/Marist تقدماً ديمقراطياً ضئيلاً قبل يوم الاقتراع."],"fr":["Les démocrates en légère tête à une semaine des élections de mi-mandat, selon un sondage","Le sondage NPR/PBS News/Marist montre une courte avance démocrate avant le jour du scrutin."],"de":["Umfrage: Demokraten eine Woche vor den US-Zwischenwahlen knapp vorn","Die Umfrage von NPR/PBS News/Marist zeigt einen knappen Vorsprung der Demokraten vor dem Wahltag."]}'::jsonb,'in_review'),
('waltz','Politics','International','single',true,false,'US envoy to the UN says the Iran war could last another year','Ambassador Mike Waltz made the remark in an interview reported by the Financial Times. BeeNews has not yet seen the original interview.','Democracy Now! (citing FT)','2026-10-23T12:00:00+04:00',true,'https://www.democracynow.org/2026/10/23/headlines',false,null,false,'{"ar":["مندوب أمريكا لدى الأمم المتحدة: حرب إيران قد تستمر عاماً آخر","أدلى السفير مايك والتز بهذا التصريح في مقابلة نقلتها فايننشال تايمز. لم تطّلع BeeNews على المقابلة الأصلية بعد."],"fr":["L''ambassadeur américain à l''ONU estime que la guerre avec l''Iran pourrait durer un an de plus","Mike Waltz l''a déclaré dans un entretien rapporté par le Financial Times. BeeNews n''a pas encore consulté l''entretien original."],"de":["US-UN-Botschafter: Iran-Krieg könnte noch ein Jahr dauern","Mike Waltz äußerte dies in einem von der Financial Times wiedergegebenen Interview. BeeNews hat das Originalinterview noch nicht gesehen."]}'::jsonb,'in_review')
